import { $state, createPortal, render } from 'fict'
import { createElement } from 'fict/internal'

export const refCalls = []
let mountedRoot
let mountedPortal

function App() {
  let value = $state('start')
  let focus = $state('blurred')
  let key = $state('none')
  let submission = $state('none')

  createPortal(mountedPortal, () => <aside data-id="portal">portal:{value}</aside>, createElement)

  return (
    <form
      data-id="form"
      onSubmit={event => {
        event.preventDefault()
        submission = `submitted:${value}`
      }}
    >
      <input
        data-id="field"
        value={value}
        ref={element => refCalls.push(element ? `attach:${element.tagName}` : 'detach')}
        onInput={event => { value = event.currentTarget.value }}
        onKeyDown={event => { key = `${event.key}:${event.shiftKey ? 'shift' : 'plain'}` }}
        onFocus={() => { focus = 'focused' }}
        onBlur={() => { focus = 'blurred' }}
      />
      <output data-id="value">{value}</output>
      <output data-id="focus">{focus}</output>
      <output data-id="key">{key}</output>
      <output data-id="submission">{submission}</output>
    </form>
  )
}

export function mount(root, portal) {
  mountedRoot = root
  mountedPortal = portal
  return render(() => <App />, root)
}

export function observe() {
  const field = mountedRoot.querySelector('[data-id="field"]')
  return {
    active: document.activeElement === field,
    field: field?.value ?? null,
    focus: mountedRoot.querySelector('[data-id="focus"]')?.textContent ?? null,
    key: mountedRoot.querySelector('[data-id="key"]')?.textContent ?? null,
    portal: mountedPortal.textContent,
    refCalls: [...refCalls],
    rootChildren: mountedRoot.childNodes.length,
    submission: mountedRoot.querySelector('[data-id="submission"]')?.textContent ?? null,
    value: mountedRoot.querySelector('[data-id="value"]')?.textContent ?? null,
  }
}
